:host(.chapter-scope) {
  --ink: #2c3e50;
  --muted: #7f8c8d;
  --accent: #2980b9;
  --warm: #e74c3c;
  --paper: #f9f9f9;
  --line: #ecf0f1;
  --si-color: #95a5a6;
  --taylor-color: #f39c12;
  --proposed-color: #27ae60;
  --crlb-color: #2c3e50;

  display: block;
  font-family: system-ui, -apple-system, sans-serif;
  color: var(--ink);
  background: var(--paper);
  padding: 2rem;
  line-height: 1.6;
}

.chapter-header h1 {
  font-size: 1.8rem;
  margin-bottom: 0.5rem;
  border-bottom: 2px solid var(--ink);
  padding-bottom: 0.5rem;
}

.lead {
  font-size: 1.1rem;
  color: var(--muted);
  margin-bottom: 2rem;
}

.content-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 3rem;
}

@media (max-width: 768px) {
  .content-grid {
    grid-template-columns: 1fr;
  }
}

h3 {
  font-size: 1.3rem;
  margin-top: 0;
  color: var(--accent);
}

.method-cards {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  margin-top: 1.5rem;
}

.method-card {
  background: #fff;
  border-left: 4px solid var(--ink);
  padding: 1rem;
  box-shadow: 0 2px 5px rgba(0,0,0,0.05);
}

.method-taylor { border-color: var(--taylor-color); }
.method-si { border-color: var(--si-color); }
.method-dac { border-color: var(--warm); }

.method-card h4 {
  margin: 0 0 0.5rem 0;
  font-size: 1.1rem;
}

.method-card ul {
  margin: 0.5rem 0;
  padding-left: 1.2rem;
  font-size: 0.95rem;
}

.source-btn {
  background: transparent;
  border: 1px solid var(--muted);
  color: var(--muted);
  font-size: 0.8rem;
  padding: 0.2rem 0.6rem;
  cursor: pointer;
  margin-top: 0.5rem;
  border-radius: 3px;
}

.source-btn:hover {
  border-color: var(--ink);
  color: var(--ink);
}

.viz-container {
  background: #fff;
  padding: 1.5rem;
  border: 1px solid var(--line);
  border-radius: 4px;
}

.viz-caption {
  font-size: 0.85rem;
  color: var(--muted);
  margin-bottom: 1rem;
}

.chart-legend {
  display: flex;
  gap: 1rem;
  margin-bottom: 1rem;
  font-size: 0.85rem;
  flex-wrap: wrap;
}

.legend-item { display: flex; align-items: center; gap: 0.4rem; }
.dot {
  width: 10px; height: 10px; border-radius: 50%; display: inline-block;
}
.dot.si { background: var(--si-color); }
.dot.taylor { background: var(--taylor-color); }
.dot.proposed { background: var(--proposed-color); }
.dot.crlb { background: var(--crlb-color); border: 1px dashed var(--crlb-color); background: transparent; }

.bar-chart-container {
  height: 250px;
  display: flex;
  align-items: flex-end;
  justify-content: space-around;
  padding-bottom: 2rem;
  border-bottom: 1px solid var(--ink);
  position: relative;
}

.bar-group {
  display: flex;
  flex-direction: column;
  align-items: center;
  width: 18%;
  height: 100%;
  justify-content: flex-end;
  position: relative;
}

.bar {
  width: 100%;
  transition: height 0.3s ease;
  min-height: 2px;
  position: relative;
}

.bar:hover::after {
  content: attr(data-val);
  position: absolute;
  top: -25px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--ink);
  color: #fff;
  font-size: 0.75rem;
  padding: 2px 4px;
  border-radius: 2px;
  white-space: nowrap;
}

.bar-label {
  margin-top: 0.5rem;
  font-size: 0.75rem;
  color: var(--muted);
}

.controls {
  margin-top: 1.5rem;
  display: flex;
  align-items: center;
  gap: 1rem;
}

select {
  padding: 0.4rem;
  border: 1px solid var(--line);
  font-size: 0.9rem;
}

.data-readout {
  margin-top: 1rem;
  font-size: 0.85rem;
  color: var(--muted);
  min-height: 1.2em;
}
button[data-source]{background:#fff!important;color:#265976!important}
.katex{display:inline-block;max-width:100%;overflow-x:auto;vertical-align:middle}.step-controls,.control-buttons{flex-wrap:wrap} @media(max-width:480px){.metric-card,.stat-card{min-width:0}}

