(function() {
  const scope = document.currentScript.closest('.chapter-scope');
  if (!scope) return;

  // Data Source: Table I (Arbitrary Array, Near Source)
  // Values parsed from runtime_data.tables where id='p8-Table_1'
  const tableData = {
    "4": { "A": 1.5768, "B": 0.7061, "C": 0.7282, "E": 0.6884 },
    "5": { "A": 0.1597, "B": 0.1460, "C": 0.1456, "E": 0.1451 },
    "6": { "A": 0.1480, "B": 0.1341, "C": 0.1359, "E": 0.1334 },
    "7": { "A": 0.1229, "B": 0.1144, "C": 0.1159, "E": 0.1143 },
    "8": { "A": 0.1164, "B": 0.1057, "C": 0.1077, "E": 0.1054 },
    "9": { "A": 0.1148, "B": 0.1034, "C": 0.1055, "E": 0.1032 },
    "10": { "A": 0.1103, "B": 0.09462, "C": 0.09697, "E": 0.09432 }
  };

  const chartContainer = scope.querySelector('#mse-chart');
  const selectEl = scope.querySelector('#sensor-select');
  const readoutEl = scope.querySelector('#data-readout');
  const resetBtn = scope.querySelector('#reset-chart');

  // Colors matching CSS variables
  const colors = {
    "A": "var(--si-color)",
    "B": "var(--taylor-color)",
    "C": "var(--proposed-color)",
    "E": "var(--crlb-color)"
  };

  const labels = {
    "A": "SI",
    "B": "Taylor",
    "C": "Proposed",
    "E": "CRLB"
  };

  function renderChart(mCount) {
    chartContainer.innerHTML = '';
    const data = tableData[mCount];
    if (!data) return;

    // Find max for scaling (SI at M=4 is huge outlier, cap for visual clarity or use log? 
    // Paper text says SI performs worst. Let's use linear scale but note the outlier.
    // Max value in this set is 1.5768. 
    const maxVal = Math.max(...Object.values(data)) * 1.1;

    Object.keys(data).forEach(key => {
      const val = data[key];
      const heightPct = (val / maxVal) * 100;

      const group = document.createElement('div');
      group.className = 'bar-group';

      const bar = document.createElement('div');
      bar.className = 'bar';
      bar.style.height = `${heightPct * 1.8}px`;
      bar.style.backgroundColor = colors[key];
      if (key === 'E') {
        bar.style.background = 'transparent';
        bar.style.borderTop = `3px dashed ${colors[key]}`;
        bar.style.height = `${Math.max(heightPct, 5) * 1.8}px`; // Ensure visible
      }
      bar.setAttribute('data-val', val.toFixed(4));

      const label = document.createElement('div');
      label.className = 'bar-label';
      label.textContent = labels[key];

      group.appendChild(bar);
      group.appendChild(label);
      chartContainer.appendChild(group);
    });

    readoutEl.textContent = `M=${mCount}: SI=${data.A.toFixed(4)}, Taylor=${data.B.toFixed(4)}, Proposed=${data.C.toFixed(4)}`;
  }

  function init() {
    renderChart(selectEl.value);
  }

  selectEl.addEventListener('change', (e) => {
    renderChart(e.target.value);
  });

  resetBtn.addEventListener('click', () => {
    selectEl.value = "4";
    renderChart("4");
  });

  init();
})();
